function intersectionWithSet(a, b) {
  const seen = new Set(a);
  const result = [];
  for (const x of b) {
    if (seen.has(x)) {
      result.push(x);
      seen.delete(x);       // report each value once
    }
  }
  return result;
}

function intersection(a, b) {
  a.sort((x, y) => x - y);
  b.sort((x, y) => x - y);
  const result = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] < b[j]) i++;
    else if (a[i] > b[j]) j++;
    else {
      if (result.length === 0 || result[result.length - 1] !== a[i]) {
        result.push(a[i]);          // record each value once
      }
      i++;
      j++;
    }
  }
  return result;
}

def intersection(a, b):
    a.sort()
    b.sort()
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            i += 1
        elif a[i] > b[j]:
            j += 1
        else:
            if not result or result[-1] != a[i]:
                result.append(a[i])       # record each value once
            i += 1
            j += 1
    return result

class Solution {
    public int[] intersection(int[] a, int[] b) {
        Arrays.sort(a);
        Arrays.sort(b);
        List<Integer> result = new ArrayList<>();
        int i = 0, j = 0;
        while (i < a.length && j < b.length) {
            if (a[i] < b[j]) i++;
            else if (a[i] > b[j]) j++;
            else {
                if (result.isEmpty() || result.get(result.size() - 1) != a[i]) {
                    result.add(a[i]);       // record each value once
                }
                i++;
                j++;
            }
        }
        return result.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution {
public:
    vector<int> intersection(vector<int>& a, vector<int>& b) {
        sort(a.begin(), a.end());
        sort(b.begin(), b.end());
        vector<int> result;
        size_t i = 0, j = 0;
        while (i < a.size() && j < b.size()) {
            if (a[i] < b[j]) i++;
            else if (a[i] > b[j]) j++;
            else {
                if (result.empty() || result.back() != a[i]) {
                    result.push_back(a[i]);   // record each value once
                }
                i++;
                j++;
            }
        }
        return result;
    }
};
